def close(x, ref, rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def same(x, ref) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    for u, v in zip(a.flat, r.flat):
        if u != v:
            print('mismatch', a, r)
            return False
    return True

def poisson2d(k: int):
    T = sp.diags_array([4. * np.ones(k), -np.ones(k - 1), -np.ones(k - 1)], offsets=[0, 1, -1])
    E = sp.diags_array([-np.ones(k - 1), -np.ones(k - 1)], offsets=[1, -1])
    return (sp.kron(sp.eye_array(k), T) + sp.kron(E, sp.eye_array(k))).tocsc()

P = poisson2d(5)
R = sp.csc_array((np.array(R_data), np.array(R_ind), np.array(R_ptr)), shape=(30, 30))
V = sp.csc_array(np.array([[1e-3, 2., 0., 0., 1.], [3., 1e-3, 1., 0., 0.], [0., 4., 2., 5., 0.],
                           [1., 0., 0., 1e-3, 2.], [0., 0., 3., 1., 1e-3]]))

def check(A, spec: str, pc, pr, lnnz: int, unnz: int, x, slack: int = 0) -> bool:
    # slack: SuperLU's supernodal update order leaves ~1e-17 round-off
    # residues in a few entries that cancel exactly in the left-looking
    # order used here (values agree to 1e-12 either way)
    lu = sl.splu(A, permc_spec=spec)
    b = np.arange(1., A.shape[0] + 1)
    ok = same(lu.perm_c, pc) and same(lu.perm_r, pr)
    ok = ok and lnnz - slack <= lu.L.nnz <= lnnz and unnz - slack <= lu.U.nnz <= unnz
    if not ok:
        print(spec, 'L/U nnz', lu.L.nnz, lnnz, lu.U.nnz, unnz)
    return ok and close(lu.solve(b), x)

@test
def test_poisson():
    assert check(P, "COLAMD", pc_P_COLAMD, pr_P_COLAMD, lnnz_P_COLAMD, unnz_P_COLAMD, x_P_COLAMD)
    assert check(P, "NATURAL", pc_P_NATURAL, pr_P_NATURAL, lnnz_P_NATURAL, unnz_P_NATURAL, x_P_NATURAL)
    assert check(P, "MMD_ATA", pc_P_MMD_ATA, pr_P_MMD_ATA, lnnz_P_MMD_ATA, unnz_P_MMD_ATA, x_P_MMD_ATA)
    assert check(P, "MMD_AT_PLUS_A", pc_P_MMD_AT_PLUS_A, pr_P_MMD_AT_PLUS_A, lnnz_P_MMD_AT_PLUS_A, unnz_P_MMD_AT_PLUS_A, x_P_MMD_AT_PLUS_A)
    lu = sl.splu(P)
    assert close(lu.L.toarray(), Ld_P) and close(lu.U.toarray(), Ud_P)
    assert same(sl.splu(P, diag_pivot_thresh=0.1).perm_r, pr_th_P)
    ls = sl.splu(P, options={"SymmetricMode": True})
    assert same(ls.perm_c, pc_sym_P) and same(ls.perm_r, pr_sym_P)
    assert close(sl.spsolve(P, np.arange(1., 26.), permc_spec="MMD_AT_PLUS_A"), xs_P)
    # P keeps scipy's explicit zeros from the BSR kron blocks
    assert sl.is_sptriangular(P) == (False, False) and sl.spbandwidth(P) == (9, 9)
    T = sp.tril(P, format='csr')
    assert sl.is_sptriangular(T) == (True, False) and sl.spbandwidth(T) == (9, 0)
test_poisson()

@test
def test_random():
    assert check(R, "COLAMD", pc_R_COLAMD, pr_R_COLAMD, lnnz_R_COLAMD, unnz_R_COLAMD, x_R_COLAMD, 6)
